  --当前模块色: var(--主题主色);
  --路由色: var(--主题主色);
  --旁白色: #f4f7fb;
  --行动色: #b77cff;
  --心声色: #00ffcc;
  --交互色: #ffd700;
  width: min(960px, 100%);
  min-width: 0;
  margin: 10px auto;
  position: relative;
  overflow: hidden;
  color: var(--文字主色);
  border: 1px solid var(--边线颜色);
  border-radius: calc(var(--投影圆角) + 8px);
  background:
    linear-gradient(160deg, color-mix(in srgb, var(--主题主色) 9%, transparent), transparent 34%),
