.dl-panel[data-font="小"] { --字号倍率: 0.92; }
.dl-panel[data-font="大"] { --字号倍率: 1.08; }

.dl-buffer {
  display: none;
}

.dl-main-stage {
  position: relative;
  z-index: 1;
  min-width: 0;
  padding: 12px;
}

.dl-header {
  display: grid;
