}

.dl-title {
  color: var(--文字主色);
  font-size: calc(15px * var(--字号倍率));
  font-weight: 900;
  letter-spacing: 0;
}

.dl-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 2px;
  color: var(--文字弱色);
  font-family: "Cascadia Code", Consolas, "Microsoft YaHei", sans-serif;
  font-size: calc(11px * var(--字号倍率));
  font-weight: 700;
}

.dl-badge {
  display: inline-flex;
  gap: 3px;
  white-space: nowrap;
}

.dl-badge strong {
  color: var(--文字主色);
}

.dl-controls {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
}

.dl-theme-button,
.dl-tool-button,
.dl-dock-button,
.dl-control-button {
  font: inherit;
}

.dl-theme-button,
.dl-tool-button,
.dl-dock-button,
.dl-control-button {
  border: 1px solid var(--边线颜色);
