}

.dl-theme-button[data-value="炫世唐门"] { background: linear-gradient(135deg, #0a192f, #00ffcc); }
.dl-theme-button[data-value="金龙王"] { background: linear-gradient(135deg, #1a0505, #ff3300 58%, #ffd700); border-radius: 0; }
.dl-theme-button[data-value="银龙王"] { background: linear-gradient(135deg, rgba(11,12,16,.6), #e0eaff); }
.dl-theme-button[data-value="幻海蝶舞"] { background: linear-gradient(135deg, #00d2ff, #ff7eb3 55%, #ffd700); }
.dl-theme-button[aria-pressed="true"] { outline: 2px solid var(--主题主色); outline-offset: 2px; }

.dl-tool-button svg,
.dl-dock-button svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.dl-route-lamp {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: var(--路由色);
