  animation: dl-pulse 1.5s ease-in-out infinite;
}

.dl-tool-button .dl-route-lamp {
  position: absolute;
  right: 1px;
  top: 1px;
}

.dl-route-text {
  color: var(--文字弱色);
  font-family: "Cascadia Code", Consolas, "Microsoft YaHei", sans-serif;
  font-size: calc(11px * var(--字号倍率));
  font-weight: 800;
}

.dl-projection-screen {
  position: relative;
  min-width: 0;
  min-height: 330px;
  padding: 14px;
  border: 1px solid var(--边线颜色);
  border-radius: var(--投影圆角);
  background: var(--投影背景);
  box-shadow: var(--主题发光), inset 0 0 22px color-mix(in srgb, var(--主题主色) 10%, transparent);
  backdrop-filter: var(--虚化强度);
  overflow: hidden;
  transform-origin: left center;
}

.dl-projection-screen::before,
.dl-projection-screen::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.dl-projection-screen::before {
