}

.dl-projection-screen::after {
  background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(0, 0, 0, 0.14) 3px 4px);
  mix-blend-mode: multiply;
  opacity: 0.38;
}

.dl-projection-head,
.dl-viewport,
.dl-dock {
