  pointer-events: auto;
  filter: none;
  transform: translateY(-1px) scale(1);
}

.dl-panel[data-folded="true"] .dl-projection-screen,
.dl-panel[data-folded="true"] .dl-dock {
  max-height: 0;
  min-height: 0;
  margin: 0;
  padding-top: 0;
  padding-bottom: 0;
  border-width: 0;
  opacity: 0;
  transform: translateY(-8px);
  pointer-events: none;
  overflow: hidden;
}

.dl-dock {
