  font-family: "Cascadia Code", Consolas, "Microsoft YaHei", sans-serif;
  font-size: calc(11px * var(--字号倍率));
  font-weight: 900;
}

.dl-dock-button.is-active {
  color: var(--文字主色);
  border-color: var(--当前模块色);
  background: color-mix(in srgb, var(--当前模块色) 16%, var(--主题底色));
  box-shadow: 0 0 16px color-mix(in srgb, var(--当前模块色) 42%, transparent);
}

.dl-card,
.dl-feed-item,
.dl-data-group,
.dl-person-cluster,
.dl-empty {
