}

.dl-field-key,
.dl-data-key,
.dl-person-key,
.dl-scene-key {
  color: var(--文字弱色);
  font-family: "Cascadia Code", Consolas, "Microsoft YaHei", sans-serif;
  font-size: calc(11px * var(--字号倍率));
  font-weight: 900;
  word-break: break-word;
}

.dl-field-value,
.dl-data-value,
.dl-person-value,
.dl-scene-value,
.dl-card-body,
.dl-feed-body,
.dl-data-body,
.dl-person-body {
