  border: 1px solid color-mix(in srgb, var(--主题主色) 52%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--主题主色) 13%, transparent);
  color: color-mix(in srgb, var(--文字主色) 76%, var(--主题主色));
