  border: 1px solid color-mix(in srgb, var(--当前模块色) 34%, transparent);
  border-left: 3px solid var(--当前模块色);
  border-radius: 0 8px 8px 0;
  background: linear-gradient(90deg, color-mix(in srgb, var(--当前模块色) 10%, transparent), transparent 58%), rgba(0, 0, 0, 0.12);
}

.dl-plan-step-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.dl-plan-step-tag {
  flex: 0 0 auto;
  color: color-mix(in srgb, var(--当前模块色) 86%, white);
  font-family: "Cascadia Code", Consolas, "Microsoft YaHei", sans-serif;
  font-size: calc(10px * var(--字号倍率));
  font-weight: 900;
  white-space: nowrap;
}

.dl-plan-step-title {
  min-width: 0;
  color: var(--文字主色);
  font-weight: 900;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dl-plan-step-body {
