<script>
(function () {
  'use strict';

  const 主题列表 = ['炫世唐门', '金龙王', '银龙王', '幻海蝶舞'];
  const 字号列表 = ['小', '标准', '大'];
  const 密度列表 = ['紧凑', '标准', '宽松'];
  const 页面列表 = ['舞台', '档案', '数据', '人物', '系统'];
  const 标签列表 = ['scene', 'npc_profile', 'stage', 'act', 'interplay', 'npc_inner', '模块路由', '剧情审查', 'dm_plan', 'recall', 'timeline_recall', '偏差账本召回', 'dmtrack', 'npc_track', 'npc_jump', 'dm_box', 'dm_set'];
  const 数据标签列表 = ['模块路由', '剧情审查', 'dm_plan', 'recall', 'timeline_recall', '偏差账本召回', 'dm_box', 'dm_set'];
  const 主题存储键 = 'lwcs_hanayume_chip_theme_v1';
  const 字号存储键 = 'lwcs_hanayume_chip_font_v1';
  const 密度存储键 = 'lwcs_hanayume_chip_density_v1';
  const 模块色表 = {
    '舞台': '#b77cff',
    '档案': '#ffd166',
    '数据': '#ff4d8d',
    '人物': '#b8f7ff',
    '系统': '#ffffff'
  };

  function 新建(标签, 类名, 文本) {
    const 节点 = document.createElement(标签);
    if (类名) 节点.className = 类名;
    if (文本 !== undefined && 文本 !== null) 节点.textContent = 文本;
    return 节点;
  }

  function 清空(节点) {
    while (节点 && 节点.firstChild) 节点.removeChild(节点.firstChild);
  }

  function 读存储(键, 默认值) {
    try {
      return localStorage.getItem(键) || 默认值;
    } catch (错误) {
      return 默认值;
    }
  }

  function 写存储(键, 值) {
    try {
      localStorage.setItem(键, 值);
    } catch (错误) {}
  }

  function 是空内容(文本) {
    return !文本 || !String(文本).replace(/[\s\u3000]+/g, '');
  }

  function 清理文本(文本) {
    return String(文本 || '').replace(/\r\n?/g, '\n').replace(/^[ \t]+$/gm, '').trim();
  }

  function 切行(文本) {
    return 清理文本(文本).split('\n').map(function (行) { return 行.trim(); }).filter(Boolean);
  }

  function 转义正则(文本) {
    return String(文本).replace(/[.*+?^${}()|[\]\\]/g, function (字符) { return '\\' + 字符; });
  }

  function 解码实体(文本) {
    return String(文本 || '')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&amp;/g, '&')
      .replace(/&#(\d+);/g, function (全词, 数字) { return String.fromCharCode(parseInt(数字, 10)); })
      .replace(/&#x([0-9a-fA-F]+);/g, function (全词, 数字) { return String.fromCharCode(parseInt(数字, 16)); });
  }

  function 解析属性(源码) {
    const 属性 = {};
    const 正则 = /([\u4e00-\u9fa5A-Za-z0-9_:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+))/gu;
    let 匹配;
    while ((匹配 = 正则.exec(源码 || ''))) {
      属性[匹配[1]] = 解码实体(匹配[2] || 匹配[3] || 匹配[4] || '');
    }
    return 属性;
  }

  function 找闭合位置(文本, 标签, 起点) {
    const 名称 = 转义正则(标签);
    const 正则 = new RegExp('</?' + 名称 + '(?:\\s[^<>]*)?>', 'giu');
    正则.lastIndex = 起点;
    let 深度 = 1;
    let 匹配;
    while ((匹配 = 正则.exec(文本))) {
      if (匹配[0].slice(0, 2) === '</') {
        深度 -= 1;
        if (!深度) return { 内容结束: 匹配.index, 结束: 正则.lastIndex };
      } else {
        深度 += 1;
      }
    }
    return null;
  }

  function 扫描标签(文本, 标签) {
    const 结果 = [];
    const 名称 = 转义正则(标签);
    const 正则 = new RegExp('<' + 名称 + '(\\s[^<>]*)?>', 'giu');
    let 匹配;
    while ((匹配 = 正则.exec(文本))) {
      const 开始 = 匹配.index;
      const 内容开始 = 正则.lastIndex;
      const 闭合 = 找闭合位置(文本, 标签, 内容开始);
      if (!闭合) continue;
      结果.push({
        标签: 标签,
        属性: 解析属性(匹配[1] || ''),
        内容: 文本.slice(内容开始, 闭合.内容结束),
        起点: 开始,
        终点: 闭合.结束,
        原始: 文本.slice(开始, 闭合.结束)
      });
      正则.lastIndex = 闭合.结束;
    }
    return 结果;
  }

  function 找下个子标签(文本, 标签们, 起点) {
    const 名称组 = 标签们.map(转义正则).join('|');
    const 正则 = new RegExp('<(' + 名称组 + ')(\\s[^<>]*)?>', 'giu');
    正则.lastIndex = 起点;
    const 匹配 = 正则.exec(文本);
    if (!匹配) return null;
    return { 标签: 匹配[1], 属性源码: 匹配[2] || '', 起点: 匹配.index, 内容开始: 正则.lastIndex };
  }

  function 拆标签流(文本, 标签们) {
    const 结果 = [];
    let 游标 = 0;
    while (游标 < 文本.length) {
      const 子 = 找下个子标签(文本, 标签们, 游标);
      if (!子) break;
      const 旁白 = 清理文本(文本.slice(游标, 子.起点));
      if (!是空内容(旁白)) 结果.push({ 类型: '旁白', 标签: 'text', 属性: {}, 内容: 旁白, 起点: 游标, 终点: 子.起点 });
      const 闭合 = 找闭合位置(文本, 子.标签, 子.内容开始);
      if (!闭合) {
        游标 = 子.内容开始;
        continue;
      }
      结果.push({
        类型: 子.标签,
        标签: 子.标签,
        属性: 解析属性(子.属性源码),
        内容: 清理文本(文本.slice(子.内容开始, 闭合.内容结束)),
        起点: 子.起点,
        终点: 闭合.结束
      });
      游标 = 闭合.结束;
    }
    const 尾声 = 清理文本(文本.slice(游标));
    if (!是空内容(尾声)) 结果.push({ 类型: '旁白', 标签: 'text', 属性: {}, 内容: 尾声, 起点: 游标, 终点: 文本.length });
    return 结果;
  }

  function 解析文档(原文) {
    const 数据 = { 原文: 原文 };
    for (const 标签 of 标签列表) 数据[标签] = 扫描标签(原文, 标签);
    数据.舞台事件 = [];
    for (const 舞台 of 数据.stage) {
      const 事件们 = 拆标签流(舞台.内容, ['act', 'npc_inner', 'interplay']);
      for (const 事件 of 事件们) 数据.舞台事件.push(事件);
    }
    if (!数据.舞台事件.length) {
      const 独立事件 = [];
      for (const 标签 of ['act', 'npc_inner', 'interplay']) {
        for (const 项 of 数据[标签]) 独立事件.push({ 类型: 标签, 标签: 标签, 属性: 项.属性, 内容: 清理文本(项.内容), 起点: 项.起点, 终点: 项.终点 });
      }
      独立事件.sort(function (甲, 乙) { return 甲.起点 - 乙.起点; });
      数据.舞台事件 = 独立事件;
    }
    数据.幕后事件 = [];
    for (const 幕后 of 数据.dmtrack) {
      const 事件们 = 拆标签流(幕后.内容, ['npc_track', 'npc_jump']);
      for (const 事件 of 事件们) 数据.幕后事件.push(事件);
    }
    return 数据;
  }

  function 取文本列表(数据, 标签) {
    return (数据[标签] || []).map(function (项) { return 清理文本(项.内容); }).filter(function (文本) { return !是空内容(文本); });
  }

  function 取首个文本(数据, 标签) {
    const 列表 = 取文本列表(数据, 标签);
    return 列表[0] || '';
  }

  function 找分隔位置(行) {
    const 位置们 = ['：', ':', '｜', '|'].map(function (符号) { return 行.indexOf(符号); }).filter(function (位置) { return 位置 > 0; });
    if (!位置们.length) return -1;
    return Math.min.apply(null, 位置们);
  }

  function 按行键值(文本) {
    return 切行(文本).map(function (行) {
      const 位置 = 找分隔位置(行);
      if (位置 < 0) return { 键: '', 值: 行 };
      return { 键: 行.slice(0, 位置).trim(), 值: 行.slice(位置 + 1).trim() };
    });
  }

  function 分解步骤(文本) {
    const 行们 = 切行(文本);
    const 结果 = [];
    let 当前 = null;
    for (const 行 of 行们) {
      const 匹配 = 行.match(/^(step\s*\d+|步骤\s*\d+|【[^】]+】)\s*[:：]?\s*(.*)$/i);
      if (匹配) {
        if (当前) 结果.push(当前);
        当前 = { 标题: 匹配[1].replace(/\s+/g, ' ').trim(), 内容: 匹配[2] || '' };
      } else if (当前) {
        当前.内容 += (当前.内容 ? '\n' : '') + 行;
      } else if (行) {
        当前 = { 标题: '前言', 内容: 行 };
      }
    }
    if (当前) 结果.push(当前);
    return 结果.length ? 结果 : [{ 标题: '前言', 内容: 清理文本(文本) }];
  }

  function 取头像字(名称) {
    const 文本 = 清理文本(名称 || 'NPC');
    return 文本.slice(0, 2).toUpperCase();
  }

  function 取摘要(文本, 长度) {
    const 单行 = 清理文本(文本).replace(/\s+/g, ' ');
    if (单行.length <= 长度) return 单行;
    return 单行.slice(0, 长度 - 1) + '...';
  }

  function 生成空态(文本) {
    return 新建('div', 'dl-empty', 文本);
  }

  function 生成字段组(文本) {
    const 容器 = 新建('div', 'dl-fields');
    const 行们 = 按行键值(文本);
    if (!行们.length && !是空内容(文本)) 行们.push({ 键: '', 值: 清理文本(文本) });
    for (const 行 of 行们) {
      const 行节点 = 新建('div', 'dl-field-row');
      const 键 = 新建('div', 'dl-field-key', 行.键 || 'text');
      const 值 = 新建('div', 'dl-field-value', 行.值);
      行节点.append(键, 值);
      容器.appendChild(行节点);
    }
    return 容器;
  }

  function 生成卡片(标题, 内容, 种类) {
    const 卡片 = 新建('section', 'dl-card');
    if (种类) 卡片.dataset.kind = 种类;
    const 头 = 新建('div', 'dl-card-head');
    const 标题节点 = 新建('div', 'dl-card-title', 标题);
    const 角标 = 新建('div', 'dl-kind', 种类 || 'DATA');
    const 身 = 新建('div', 'dl-card-body');
    身.appendChild(生成字段组(内容));
    头.append(标题节点, 角标);
    卡片.append(头, 身);
    return 卡片;
  }

  function 生成文本卡(标题, 内容, 种类) {
    const 卡片 = 新建('section', 'dl-card');
    if (种类) 卡片.dataset.kind = 种类;
    const 头 = 新建('div', 'dl-card-head');
    const 标题节点 = 新建('div', 'dl-card-title', 标题);
    const 角标 = 新建('div', 'dl-kind', 种类 || 'TEXT');
    const 身 = 新建('div', 'dl-card-body', 清理文本(内容));
    头.append(标题节点, 角标);
    卡片.append(头, 身);
    return 卡片;
  }

  function 生成舞台项(事件) {
    const 类型表 = { act: '行动', npc_inner: '心声', interplay: '交互', text: '旁白', '旁白': '旁白' };
    const 类型 = 类型表[事件.标签] || 类型表[事件.类型] || '旁白';
    const 名称 = 事件.属性.name || (类型 === '旁白' ? '剧情' : 类型);
    const 项 = 新建('article', 'dl-feed-item');
    项.dataset.kind = 类型;
    const 头 = 新建('div', 'dl-feed-head');
    const 标题 = 新建('div', 'dl-feed-title', 类型 === '旁白' ? '剧情旁白' : 名称);
    const 角标 = 新建('div', 'dl-kind', 类型);
    const 身 = 新建('div', 'dl-feed-body');
    身.appendChild(生成字段组(事件.内容));
    头.append(标题, 角标);
    项.append(头, 身);
    return 项;
  }

  function 生成数据组(标题, 文本们, 默认展开) {
    const 模式 = 标题 === '推进计划' ? 'plan' : (标题 === '记忆召回' || 标题 === '时间线召回' || 标题 === '偏差账本召回' ? 'long' : '');
    const 组 = 新建('details', 'dl-data-group' + (模式 === 'plan' ? ' dl-plan-group' : '') + (模式 === 'long' ? ' dl-long-group' : ''));
    if (默认展开) 组.open = true;
    const 头 = 新建('summary');
    const 标题节点 = 新建('div', 'dl-data-title', 标题);
    let 字数 = 0;
    let 步数 = 0;
    for (const 文本 of 文本们) {
      const 清理 = 清理文本(文本);
      字数 += 清理.length;
      if (模式 === 'plan') 步数 += 分解步骤(文本).length;
    }
    let 计数文本 = String(文本们.length) + '段';
    if (模式 === 'plan') 计数文本 += '/' + 步数 + '步';
    const 计数 = 新建('div', 'dl-count', 计数文本 + (字数 > 800 ? '/' + 字数 + '字' : ''));
    const 身 = 新建('div', 'dl-data-body');
    头.append(标题节点, 计数);
    if (模式 === 'plan') {
      let 索引 = 0;
      for (const 文本 of 文本们) {
        const 分段 = 分解步骤(文本);
        for (const 段 of 分段) {
          索引 += 1;
          const 步 = 新建('article', 'dl-plan-step');
          const 头行 = 新建('div', 'dl-plan-step-head');
          const 角标 = 新建('div', 'dl-plan-step-tag', String(索引).padStart(2, '0'));
          const 标题行 = 新建('div', 'dl-plan-step-title', 段.标题 || '前言');
          头行.append(角标, 标题行);
          步.append(头行, 新建('div', 'dl-plan-step-body', 段.内容 || ''));
          身.appendChild(步);
        }
      }
    } else if (模式 === 'long') {
      let 索引 = 0;
      for (const 文本 of 文本们) {
        索引 += 1;
        const 清理 = 清理文本(文本);
        const 首行 = 清理.split('\n').find(function (行) { return 行.trim(); }) || 清理;
        const 条 = 新建('article', 'dl-long-item');
        const 头行 = 新建('div', 'dl-long-head');
        头行.append(新建('div', 'dl-long-title', '块 ' + 索引), 新建('div', 'dl-long-summary', 取摘要(首行, 72)));
        条.append(头行, 新建('div', 'dl-long-body', 清理));
        身.appendChild(条);
      }
    } else {
      for (const 文本 of 文本们) {
        const 分段 = 分解步骤(文本);
        for (const 段 of 分段) {
          const 行 = 新建('div', 'dl-data-row');
          行.append(新建('div', 'dl-data-key', 段.标题), 新建('div', 'dl-data-value', 段.内容 || 文本));
          身.appendChild(行);
        }
      }
    }
    组.append(头, 身);
    return 组;
  }

  function 分解场景(文本) {
    const 清理 = 清理文本(文本);
    if (!清理) return [];
    const 切片 = 清理.split(/[｜|]/).map(function (项) { return 项.trim(); }).filter(Boolean);
    if (切片.length > 1) {
      return 切片.map(function (值, 索引) { return { 键: ['时间', '地点', '环境', '状态'][索引] || '字段' + (索引 + 1), 值: 值 }; });
    }
    return 按行键值(清理);
  }

  function 取人物名集合(数据) {
    const 集合 = new Set();
    const 收 = function (名称) {
      if (!是空内容(名称)) 集合.add(清理文本(名称));
    };
    for (const 项 of 数据.npc_profile) 收(项.属性.name);
    for (const 项 of 数据.act) 收(项.属性.name);
    for (const 项 of 数据.npc_inner) 收(项.属性.name);
    for (const 项 of 数据.npc_track) 收(项.属性.name);
    for (const 项 of 数据.npc_jump) 收(项.属性.name);
    return 集合;
  }

  function 取路由状态(文本) {
    const 小写 = 清理文本(文本).toLowerCase();
    if (/battle|战斗|冲突/.test(小写)) return { 名称: 'battle', 色: '#ff4a2f' };
    if (/check|检定|审查/.test(小写)) return { 名称: 'check', 色: '#ffd166' };
    if (/trade|交易/.test(小写)) return { 名称: 'trade', 色: '#42d392' };
    if (/map|地图|移动/.test(小写)) return { 名称: 'map', 色: '#00d2ff' };
    if (/未命中|无/.test(小写)) return { 名称: 'idle', 色: '#8ba9b7' };
    return { 名称: 小写 ? 'route' : 'idle', 色: '#8ba9b7' };
  }

  function 渲染舞台(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="舞台页"]');
    清空(容器);
    for (const 事件 of 数据.舞台事件) 容器.appendChild(生成舞台项(事件));
    if (!数据.舞台事件.length) 容器.appendChild(生成空态('无舞台'));
    return 数据.舞台事件.length;
  }

  function 渲染档案(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="档案页"]');
    清空(容器);
    const 网格 = 新建('div', 'dl-profile-grid');
    for (const 项 of 数据.npc_profile) {
      const 名称 = 项.属性.name || 'NPC';
      网格.appendChild(生成卡片(名称, 清理文本(项.内容), 取头像字(名称)));
    }
    if (网格.children.length) 容器.appendChild(网格);
    else 容器.appendChild(生成空态('无档案'));
    return 数据.npc_profile.length;
  }

  function 统计数据数量(数据) {
    let 数量 = 0;
    for (const 标签 of 数据标签列表) 数量 += (数据[标签] || []).length;
    return 数量;
  }

  function 渲染数据(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="数据页"]');
    清空(容器);
    let 数量 = 0;
    const 分组 = [
      ['推进计划', 取文本列表(数据, 'dm_plan'), true],
      ['模块路由', 取文本列表(数据, '模块路由'), false],
      ['剧情审查', 取文本列表(数据, '剧情审查'), false],
      ['记忆召回', 取文本列表(数据, 'recall'), false],
      ['时间线召回', 取文本列表(数据, 'timeline_recall'), false],
      ['偏差账本召回', 取文本列表(数据, '偏差账本召回'), false],
      ['幕后盒', 取文本列表(数据, 'dm_box'), false],
      ['本轮设置', 取文本列表(数据, 'dm_set'), false]
    ];
    for (const 组 of 分组) {
      if (!组[1].length) continue;
      容器.appendChild(生成数据组(组[0], 组[1], 组[2]));
      数量 += 组[1].length;
    }
    if (!数量) 容器.appendChild(生成空态('无数据'));
    return 数量;
  }

  function 取人物桶(人物表, 名称) {
    const 键 = 清理文本(名称 || '幕后');
    if (!人物表.has(键)) 人物表.set(键, []);
    return 人物表.get(键);
  }

  function 渲染人物(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="人物页"]');
    清空(容器);
    const 人物表 = new Map();
    for (const 项 of 数据.npc_inner) 取人物桶(人物表, 项.属性.name || 'NPC').push({ 类型: 'inner', 内容: 清理文本(项.内容) });
    for (const 事件 of 数据.幕后事件) {
      if (事件.标签 === 'npc_track') 取人物桶(人物表, 事件.属性.name || 'NPC').push({ 类型: 'track', 内容: 事件.内容 });
      else if (事件.标签 === 'npc_jump') 取人物桶(人物表, 事件.属性.name || 'NPC').push({ 类型: 事件.属性['跃过时间'] ? 'jump · ' + 事件.属性['跃过时间'] : 'jump', 内容: 事件.内容 });
      else 取人物桶(人物表, '幕后').push({ 类型: 'dmtrack', 内容: 事件.内容 });
    }
    const 网格 = 新建('div', 'dl-person-grid');
    for (const 组 of 人物表.entries()) {
      const 卡 = 新建('section', 'dl-person-cluster');
      const 头 = 新建('div', 'dl-person-head');
      头.append(新建('div', 'dl-person-name', 组[0]), 新建('div', 'dl-count', String(组[1].length)));
      const 身 = 新建('div', 'dl-person-body');
      for (const 项 of 组[1]) {
        const 行 = 新建('div', 'dl-person-row');
        行.append(新建('div', 'dl-person-key', 项.类型), 新建('div', 'dl-person-value', 项.内容));
        身.appendChild(行);
      }
      卡.append(头, 身);
      网格.appendChild(卡);
    }
    if (网格.children.length) 容器.appendChild(网格);
    else 容器.appendChild(生成空态('无人物'));
    return 人物表.size;
  }

  function 渲染系统(面板) {
    const 容器 = 面板.querySelector('[data-role="系统页"]');
    清空(容器);
    const 网格 = 新建('div', 'dl-system-grid');
    const 控制组们 = [
      ['主题', 主题列表, 'theme', 面板.dataset.theme],
      ['字号', 字号列表, 'font', 面板.dataset.font],
      ['密度', 密度列表, 'density', 面板.dataset.density]
    ];
    for (const 组 of 控制组们) {
      const 卡 = 新建('section', 'dl-card');
      const 标题 = 新建('div', 'dl-control-title', 组[0]);
      const 行 = 新建('div', 'dl-control-row');
      for (const 值 of 组[1]) {
        const 按钮 = 新建('button', 'dl-control-button', 值);
        按钮.type = 'button';
        按钮.dataset.action = 组[2];
        按钮.dataset.value = 值;
        按钮.setAttribute('aria-pressed', 值 === 组[3] ? 'true' : 'false');
        if (值 === 组[3]) 按钮.classList.add('is-active');
        行.appendChild(按钮);
      }
      卡.append(标题, 行);
      网格.appendChild(卡);
    }
    容器.appendChild(网格);
    return 3;
  }

  function 设置主题(面板, 主题) {
    const 值 = 主题列表.includes(主题) ? 主题 : 主题列表[0];
    面板.dataset.theme = 值;
    写存储(主题存储键, 值);
    for (const 按钮 of 面板.querySelectorAll('[data-action="theme"]')) {
      const 激活 = 按钮.dataset.value === 值;
      按钮.classList.toggle('is-active', 激活);
      按钮.setAttribute('aria-pressed', 激活 ? 'true' : 'false');
    }
    渲染系统(面板);
  }

  function 设置字号(面板, 字号) {
    const 值 = 字号列表.includes(字号) ? 字号 : '标准';
    面板.dataset.font = 值;
    写存储(字号存储键, 值);
    for (const 按钮 of 面板.querySelectorAll('[data-action="font"]')) {
      const 激活 = 按钮.dataset.value === 值;
      按钮.classList.toggle('is-active', 激活);
      按钮.setAttribute('aria-pressed', 激活 ? 'true' : 'false');
    }
    渲染系统(面板);
  }

  function 设置密度(面板, 密度) {
    const 值 = 密度列表.includes(密度) ? 密度 : '标准';
    面板.dataset.density = 值;
    写存储(密度存储键, 值);
    for (const 按钮 of 面板.querySelectorAll('[data-action="density"]')) {
      const 激活 = 按钮.dataset.value === 值;
      按钮.classList.toggle('is-active', 激活);
      按钮.setAttribute('aria-pressed', 激活 ? 'true' : 'false');
    }
    渲染系统(面板);
  }

  function 设置页面(面板, 页面) {
    if (!页面列表.includes(页面)) 页面 = '舞台';
    面板.dataset.page = 页面;
    面板.style.setProperty('--当前模块色', 模块色表[页面] || 'var(--主色)');
    const 标题 = 面板.querySelector('[data-role="视图标题"]');
    if (标题) 标题.textContent = 页面;
    for (const 页 of 面板.querySelectorAll('.dl-page')) 页.classList.toggle('is-active', 页.dataset.page === 页面);
    for (const 按钮 of 面板.querySelectorAll('[data-page-target]')) {
      const 激活 = 按钮.dataset.pageTarget === 页面;
      按钮.classList.toggle('is-active', 激活);
      按钮.setAttribute('aria-selected', 激活 ? 'true' : 'false');
      if (激活) 面板.style.setProperty('--当前模块色', 按钮.style.getPropertyValue('--按钮色') || 模块色表[页面]);
    }
  }

  function 设置折叠(面板, 折叠) {
    面板.dataset.folded = 折叠 ? 'true' : 'false';
    const 按钮 = 面板.querySelector('[data-action="折叠"]');
    if (按钮) 按钮.setAttribute('aria-expanded', 折叠 ? 'false' : 'true');
  }

  function 设置路由(面板, 文本) {
    const 状态 = 取路由状态(文本);
    面板.style.setProperty('--路由色', 状态.色);
    const 路由文字 = 面板.querySelector('[data-role="路由文字"]');
    if (路由文字) 路由文字.textContent = 状态.名称;
  }

  function 更新角标(面板, 数据, 数据数) {
    const 映射 = [
      ['NPC角标', 取人物名集合(数据).size],
      ['召回角标', 取文本列表(数据, 'recall').length + 取文本列表(数据, 'timeline_recall').length + 取文本列表(数据, '偏差账本召回').length],
      ['档案角标', 数据.npc_profile.length],
      ['数据角标', 数据数]
    ];
    for (const 项 of 映射) {
      const 节点 = 面板.querySelector('[data-role="' + 项[0] + '"]');
      if (节点) 节点.textContent = String(项[1]);
    }
    const 场景标题 = 面板.querySelector('[data-role="场景标题"]');
    if (场景标题) 场景标题.textContent = 取摘要(取首个文本(数据, 'scene') || '未捕获场景', 54);
  }

  function 绑定交互(面板) {
    面板.addEventListener('click', function (事件) {
      const 页面按钮 = 事件.target.closest('[data-page-target]');
      if (页面按钮 && 面板.contains(页面按钮)) {
        设置页面(面板, 页面按钮.dataset.pageTarget);
        return;
      }
      const 动作按钮 = 事件.target.closest('[data-action]');
      if (!动作按钮 || !面板.contains(动作按钮)) return;
      const 动作 = 动作按钮.dataset.action;
      if (动作 === '折叠') 设置折叠(面板, 面板.dataset.folded !== 'true');
      if (动作 === 'theme') 设置主题(面板, 动作按钮.dataset.value);
      if (动作 === 'font') 设置字号(面板, 动作按钮.dataset.value);
      if (动作 === 'density') 设置密度(面板, 动作按钮.dataset.value);
    });
  }

  function 启动(面板) {
    if (!面板 || 面板.dataset.ready === 'true') return;
    面板.dataset.ready = 'true';
    面板.dataset.theme = 读存储(主题存储键, 面板.dataset.theme || 主题列表[0]);
    面板.dataset.font = 读存储(字号存储键, 面板.dataset.font || '标准');
    面板.dataset.density = 读存储(密度存储键, 面板.dataset.density || '标准');
    const 缓冲 = 面板.querySelector('.dl-buffer');
    const 数据 = 解析文档(缓冲 ? 缓冲.value : '');
    面板.__全息数据 = 数据;
    渲染舞台(面板, 数据);
    渲染档案(面板, 数据);
    const 数据数 = 渲染数据(面板, 数据);
    渲染人物(面板, 数据);
    渲染系统(面板);
    更新角标(面板, 数据, 数据数);
    设置路由(面板, 取首个文本(数据, '模块路由'));
    设置页面(面板, '舞台');
    绑定交互(面板);
  }

  for (const 面板 of document.querySelectorAll('.dl-panel')) 启动(面板);
})();
</script>
</html>
